	@Test
	public void closesLeftWhenRightEvaluationFailsAndPreservesCloseFailure() {
		AtomicInteger leftCloseCount = new AtomicInteger();
		QueryEvaluationException rightFailure = new QueryEvaluationException("right evaluation failed");
		QueryEvaluationException leftCloseFailure = new QueryEvaluationException("left close failed");
		CloseableIteration<BindingSet> leftIteration = new CloseableIteration<>() {
			@Override
			public boolean hasNext() {
				return false;
			}

			@Override
			public BindingSet next() {
				throw new AssertionError("left iteration should be empty");
			}

			@Override
			public void close() {
				leftCloseCount.incrementAndGet();
				throw leftCloseFailure;
			}
		};
		QueryEvaluationStep left = ignored -> leftIteration;
		QueryEvaluationStep right = ignored -> {
			throw rightFailure;
		};

		QueryEvaluationException actual = assertThrows(QueryEvaluationException.class,
				() -> new HashJoinIteration(left, right, EmptyBindingSet.getInstance(), false, new String[0],
						new QueryEvaluationContext.Minimal(null)));

		assertSame(rightFailure, actual);
		assertEquals(1, leftCloseCount.get(), "the already-open left iteration must be closed exactly once");
		assertEquals(1, actual.getSuppressed().length);
		assertSame(leftCloseFailure, actual.getSuppressed()[0], "left cleanup failure must remain suppressed");
	}

	@Test
	public void jaggedUndefJoinRowsUseCompatibilitySemantics() throws QueryEvaluationException {
		QueryBindingSet leftRow = new QueryBindingSet();
		leftRow.addBinding("x", vf.createIRI("urn:outer"));
		QueryBindingSet rightRow = new QueryBindingSet();
		rightRow.setBinding("x", null);
		rightRow.addBinding("y", vf.createLiteral(1));

		CloseableIteration<BindingSet> left = new CloseableIteratorIteration<>(List.<BindingSet>of(leftRow).iterator());
		CloseableIteration<BindingSet> right = new CloseableIteratorIteration<>(
				List.<BindingSet>of(rightRow).iterator());
		try (HashJoinIteration iteration = new HashJoinIteration(left, Set.of("x"), right, Set.of("x", "y"), false)) {
			assertTrue(iteration.hasNext(), "an unbound shared name must not block a compatible mapping");
			BindingSet result = iteration.next();
			assertEquals(vf.createIRI("urn:outer"), result.getValue("x"));
			assertEquals(vf.createLiteral(1), result.getValue("y"));
			assertFalse(iteration.hasNext());
		}
	}

