	@Test
	public void compatibleHashValueIteratorsAreClosedThroughTheProtectedHook() throws QueryEvaluationException {
		QueryBindingSet leftRow = new QueryBindingSet();
		leftRow.addBinding("x", vf.createIRI("urn:outer"));
		QueryBindingSet rightRow = new QueryBindingSet();
		rightRow.setBinding("x", null);

		CloseableIteration<BindingSet> left = new CloseableIteratorIteration<>(List.<BindingSet>of(leftRow).iterator());
		CloseableIteration<BindingSet> right = new CloseableIteratorIteration<>(
				List.<BindingSet>of(rightRow).iterator());
		TrackingHashJoinIteration iteration = new TrackingHashJoinIteration(left, right);
		try {
			assertTrue(iteration.hasNext());
			assertEquals(vf.createIRI("urn:outer"), iteration.next().getValue("x"));
			assertFalse(iteration.hasNext());
			assertTrue(iteration.closedHashIterators.get() > 0,
					"the compatibility wrapper must dispose the active hash-value iterator");
		} finally {
			iteration.close();
		}
	}

	@Test
	public void earlyCloseDisposesTheActualHashValueIteratorThroughTheProtectedHook()
			throws QueryEvaluationException {
		QueryBindingSet leftRow = new QueryBindingSet();
		leftRow.setBinding("x", null);
		QueryBindingSet secondLeftRow = new QueryBindingSet();
		secondLeftRow.setBinding("x", null);
		QueryBindingSet rightRow = new QueryBindingSet();
		rightRow.addBinding("x", vf.createIRI("urn:outer"));
		QueryBindingSet secondRightRow = new QueryBindingSet();
		secondRightRow.addBinding("x", vf.createIRI("urn:outer"));
		QueryBindingSet thirdRightRow = new QueryBindingSet();
		thirdRightRow.addBinding("x", vf.createIRI("urn:outer"));

		CloseableIteration<BindingSet> left = new CloseableIteratorIteration<>(
				List.of(leftRow, secondLeftRow).iterator());
		CloseableIteration<BindingSet> right = new CloseableIteratorIteration<>(
				List.of(rightRow, secondRightRow, thirdRightRow).iterator());
		TrackingHashJoinIteration iteration = new TrackingHashJoinIteration(left, right);
		try {
			assertTrue(iteration.hasNext());
			assertEquals(vf.createIRI("urn:outer"), iteration.next().getValue("x"));
			assertEquals(0, iteration.closedHashIterators.get(),
					"the active hash candidate must remain owned until the join closes");
		} finally {
			iteration.close();
		}
		assertEquals(1, iteration.closedHashIterators.get(),
				"early close must dispose the concrete hash-value iterator exactly once");
	}

	private static final class TrackingHashJoinIteration extends HashJoinIteration {
		private final AtomicInteger closedHashIterators = new AtomicInteger();

		private TrackingHashJoinIteration(CloseableIteration<BindingSet> left, CloseableIteration<BindingSet> right)
				throws QueryEvaluationException {
			super(left, Set.of("x"), right, Set.of("x"), false);
		}

		@Override
		protected List<BindingSet> makeHashValue(int currentMaxListSize) {
			return new TrackingList(closedHashIterators);
		}

		@Override
		protected <E> void closeHashValue(Iterator<E> iterator) {
			if (iterator instanceof TrackingIterator trackingIterator) {
				trackingIterator.close();
			}
		}
	}

	private static final class TrackingList extends ArrayList<BindingSet> {
		private final AtomicInteger closeCount;

		private TrackingList(AtomicInteger closeCount) {
			this.closeCount = closeCount;
		}

		@Override
		public Iterator<BindingSet> iterator() {
			return new TrackingIterator(super.iterator(), closeCount);
		}
	}

	private static final class TrackingIterator extends CloseableIteratorIteration<BindingSet> {
		private final AtomicInteger closeCount;

		private TrackingIterator(Iterator<BindingSet> delegate, AtomicInteger closeCount) {
			super(delegate);
			this.closeCount = closeCount;
		}

		@Override
		protected void handleClose() {
			closeCount.incrementAndGet();
			super.handleClose();
		}
	}
